<template>
    <div class="layers">
        <div class="item">
            <h3>实时车队数据</h3>
            <ul>

                <li @click="changeNormalLayerType(item.type)" v-for="item in normalLayer"
                    :class="item.check?'active':''">
                    <img :src="item.url" alt="icon">
                    <span>{{ item.name }}</span>
                </li>
            </ul>
        </div>
        <div class="item">
            <h3>路网状态</h3>
            <ul>
                <li @click="changeRoadNetLayerType(item.type)" v-for="item in roadNetLayer"
                    :class="item.check?'active':''">
                    <img :src="item.url" alt="icon">
                    <span>{{ item.name }}</span>
                </li>
                <li @click="changeVehicleEventType()"
                    :class="vehicleEvent.check?'active':''"> <img :src="vehicleEvent.url" alt="icon">
                  <span>{{ vehicleEvent.name }}</span>
                </li>
            </ul>
        </div>
        <div class="item">
            <h3>实时气象数据</h3>
            <ul>
                <li @click="changeMeteorologyLayerType(item.type)" v-for="item in changeMeteorologyLayer"
                    :class="item.check?'active':''">
                    <img :src="item.url" alt="icon">
                    <span>{{ item.name }}</span>
                </li>
            </ul>
        </div>
    </div>
</template>

<script>
import {mapState} from "vuex";
export default {
    data() {
        return {
            normalLayer: [
                // {name: '标定车辆', type: 1, url: require('../assets/img/layer/layer_icon_01.png'), check: false},
                {name: '联网车辆', type: 2, url: require('../assets/img/layer/layer_icon_02.png'), check: true},
            ],
            roadNetLayer: [
                {name: '路面干湿状态图层', type: 'slippery', url: require('../assets/img/layer/layer_icon_04.png'), check: false}, //slippery
                {name: '路面附着系数图层', type: 'friction', url: require('../assets/img/layer/layer_icon_03.png'), check: false}, //friction
                {name: '路面温度状态图层', type: 'temperature', url: require('../assets/img/layer/layer_icon_07.png'), check: false}, //friction
            ],
            vehicleEvent: {name: '路面积水颠簸事件', type: 'event', url: require('../assets/img/layer/layer_icon_05.png'), check: true}, //friction,
            changeMeteorologyLayer: [
                {name: '降水量', type: 1, url: require('../assets/img/layer/layer_icon_06.png'), check: false},
                {name: '查看气象设备', type: 2, url: require('../assets/img/layer/layer_icon_06.png'), check: false},
            ]
        }
    },
    // watch:{
    //   selectBur(val){
    //     if(val != 1){
    //       this.normalLayer.map(item => {
    //         if (item.check) {
    //           item.check = !item.check;
    //           return item;
    //         }
    //       })
    //     }
    //   }
    // },
    methods: {
        //切换车辆路侧图层
        changeNormalLayerType(type) {
          // if(this.selectBur != 1){
          //   return
          // }
          var nCheck = false
          this.normalLayer.map(item => {
              if (type === item.type) {
                  item.check = !item.check;
                  nCheck = item.check;
                  return item;
              }
          })

          let obj = {type:type,check:nCheck}
          this.$emit('changeNormalLayerType', obj);
        },
        //切换路网图层
        changeRoadNetLayerType(type) {

          this.roadNetLayer.map(item => {
              if (type === item.type) {
                  if(item.check){
                    item.check = false
                  }else {
                    item.check = true
                  }
              } else {
                  item.check = false;
              }
              return item;
          })
            let roadNetLayerItem = this.roadNetLayer.filter(item => item.type == type)
            this.$emit('changeRoadNetLayer', roadNetLayerItem);
        },
        // 切换车辆上报事件
        changeVehicleEventType(){
          if(this.vehicleEvent.check){
            this.vehicleEvent.check = false
          }else {
            this.vehicleEvent.check = true
          }
          this.$emit('changeVehicleEventType' , this.vehicleEvent.check)
        },
         //切换气象数据图层
        changeMeteorologyLayerType(type) {
          var nCheck = false
            this.changeMeteorologyLayer.map(item => {
              if (type === item.type) {
                item.check = !item.check;
                nCheck = item.check
                return item;
              }
            })
          let obj = {type:type,check:nCheck}
          this.$emit('changeMeteorologicalType', obj);
        }
    },
    // computed:{
    //   ...mapState(['selectBur'])
    // },
}
</script>

<style scoped lang="scss" src="../assets/css/layer.scss"></style>
