    methods: {
      renderMovingVehicles() {
        this.isRenderingOnlineVehicles = true;

        http.get("/location")
            .then(res => {
              try {
                if (!res || !res.data) {
                  throw new Error("响应数据为空");
                }

                const tempCarObject = res.data;
                this.allVehicleData = tempCarObject;
                const currentKeys = Object.keys(tempCarObject);
                const allCarKeys = [...new Set([
                  ...Object.keys(tempCarObject),
                  ...Object.keys(this.onlineVehicleMarkers)
                ])];

                const MAX_MOVE_DISTANCE = 150; // 米. 如果位移距离大于150米，则不移动小车，而是让小车瞬移到新点上

                allCarKeys.forEach((key) => {
                  if (currentKeys.includes(key)) {
                    const coordinates = tempCarObject[key].coordinates;

                    if (this.onlineVehicleMarkers[key]) {
                      const marker = this.onlineVehicleMarkers[key];
                      const oldPos = marker.getPosition();
                      const newPos = new AMap.LngLat(coordinates.longitude, coordinates.latitude);

                      const distance = oldPos ? newPos.distance(oldPos) : 0;
                      const shouldAnimate = !this.isPageHidden && distance < MAX_MOVE_DISTANCE;

                      this.moveVehicle(marker, coordinates, shouldAnimate);
                    } else {
                      this.createVehicleMaker2(key, tempCarObject[key]);
                    }
                  } else if (this.onlineVehicleMarkers[key]) {
                    this.map.remove(this.onlineVehicleMarkers[key]);
                    this.onlineVehicleMarkers[key] = null;
                  }
                });

              } catch (error) {
                console.error("渲染车辆时出错:", error);
              } finally {
                this.scheduleNextPoll();
              }
            })
            .catch(error => {
              console.error("HTTP请求失败:", error);
              this.scheduleNextPoll();
            });
      },

      scheduleNextPoll() {
        if (this.fetchOnlineVehicleTimer) {
          clearTimeout(this.fetchOnlineVehicleTimer);
        }
        this.fetchOnlineVehicleTimer = setTimeout(() => {
          this.renderMovingVehicles();
        }, 1500);
      },

      stopRenderingMovingVehicles() {
        this.isRenderingOnlineVehicles = false;
        if (this.fetchOnlineVehicleTimer) {
          clearTimeout(this.fetchOnlineVehicleTimer);
          this.fetchOnlineVehicleTimer = null;
        }
