        if (animate) {
          // marker.moveTo(target, 800, function (k) {
          //   return k;
          // });
          marker.moveTo(target, {
            duration: 300,
            delay: 0,
            autoRotation: true,
            easing: function(t){return t}

          });
        } else {
          marker.setPosition(target);
        }
      },

