      eesVehicleInfo(val){
        this.vehicleData = val
        // var that = this
        if(this.testVehiclesMakers.length != val.length || !this.isShowTestCarMaker){
          return;
        }

        val.forEach(item =>{
          if(item.vin == 'rcs-001') {

            this.movingVehicles(this.testVehiclesMakers[0], item.coordinates)

            if (this.isDrawNet) {

              this.createV1PolylineArray(item)

            }
          }
          if(item.vin == 'rcs-002'){

            this.movingVehicles(this.testVehiclesMakers[1],item.coordinates)

            if(this.isDrawNet){
              this.createV2PolylineArray(item)
            }
          }
        })

