      //AA车辆数据
      eesAACarInfo(carList){
        this.aaVehicleData = carList
        if (this.map === undefined || this.map===null) {
          this.aaCarInfo=[];
          this.recordAACarInfo(carList)
          return
        }

        if( !this.isAACarShow){
          this.aaCarInfo=[];
          this.recordAACarInfo(carList)
          this.removeVehicleMakers()
          return
        }


        carList.forEach((info, index) => {
          if (this.aaCarInfo.length > 0) {
            if (this.aaCarInfo[index].isOnline == 1) {
              if (info.isOnline == 1) {
                if (this.aaCarMakers[index] === undefined || this.aaCarMakers[index]===null){
                  this.initAACarMarkers()
                }
                this.movingVehicles(this.aaCarMakers[index], info.coordinates)
              }
              else {
                this.map.remove(this.aaCarMakers[index])
              }
            } else {
              if (info.isOnline == 1) {
                this.map.add(this.aaCarMakers[index])
              } else {
                this.map.remove(this.aaCarMakers[index])
              }
            }
          } else {
            this.initAACarMarkers()
          }
        })
        this.recordAACarInfo(carList)
      },
