        getServerTime(data){
          let hour = new Date(data).getHours()
          let minute = new Date(data).getMinutes().toString()

          if(minute == 0 && hour >= (this.systemHour + 1)){
            this.systemHour = hour
            this.initTime()
            if(this.historyTime > 1 ){
              if(this.curTime != 1){
                let ctime = this.curTime
                let htime = this.historyTime
                this.curTime = ctime - 1
                this.historyTime = htime + 1
                this.$store.commit('SET_SELECTBUR',htime)
              }

            }else {
              this.changeRoadNet()
            }


          }else {
            if(minute == 15 || minute == 30 || minute == 45 ){
              this.changeRoadNet()
            }
          }

