        initTime(){
          //marks 默认有序 无视插入顺序
          let nowTime = new Date().getTime()
          let value = new Date().getHours()
          if(this.systemHour == 0){
            this.systemHour = value
          }
          // let minuteValue = new Date().getMinutes()
          // if(this.roadNetType != "turbulence"){
              this.$set(this.marks, 25 , (value+1)+':00')
          // }

          this.$set(this.marks, 24 ,'Now')
          for (let i = 1; i < 24; i++) {
            value = new Date(nowTime - (60*60*1000*(24-i))).getHours()
            this.$set(this.marks, i ,value+':00')
          }

