        },
        createEventMaker(data,itemData){
            let eventMarker = new AMap.Marker({
              map: this.map,
              icon: data.icon,
              position: data.position,
              offset: new AMap.Pixel(-40, -75),
              zooms: [10,18],
              extData:itemData
            });

            //if(data.type !== "event"){
              console.log("data.type not event");
              switch (data.option){
                case 'roadCamber':
                  // console.log("createEventMaker roadCamber ");
                  // console.log(itemData);
                  eventMarker.setContent(this.getBumpIconContent(itemData.level));
                  //eventMarker.setIcon( this.getBumpIconContent(itemData.level));
                  eventMarker.setAnchor("middle-center");
                  eventMarker.setOffset(new AMap.Pixel(0, 0));
                  this.roadCamberMakerList.push(eventMarker)
                  break
                case 'slippery':
                  this.slipperyPointMakerList.push(eventMarker)
                  break
                case 'water':
                  this.waterPointMakerList.push(eventMarker)
                  break
                case 'ice':
                  this.icePointMakerList.push(eventMarker)
                  break
                case 'lowAttachment':
                  this.lowAttachmentMakerList.push(eventMarker)
                  break
              }

            //}

            eventMarker.on('click', (e) => {
              this.openEventMakerWindow(e)
              this.eventMakerInfo = e.target
              let roadEventType = e.target.getExtData().eventType
              switch (roadEventType){
                case 'bumpy_event':
                  this.makerTitle = "颠簸"
                  break
                case 'slippery_event':
                  this.makerTitle = "湿滑"
                  break
                case 'ponding_event':
                  this.makerTitle = "积水"
                  break
                case 'ice_event':
                  this.makerTitle = "结冰"
                  break
                case 'low_attachment_event':
                  this.makerTitle = "低附着"
                  break
              }

            });

        },
        selectMakerBtn(val){
          if(val){
            http.post("/delete-event",{
              eventType:this.eventMakerInfo.getExtData().eventType,
              eventId: this.eventMakerInfo.getExtData().eventId
            }).then(res =>{
              console.log(res.data)
            })
            this.map.remove(this.eventMakerInfo)
            this.map.clearInfoWindow();
            //更新告警列表
            this.$nextTick(()=>{
              this.$emit("deleteEvent",val)
            })
          }else {
            this.map.clearInfoWindow();
          }
        },
        //打开事件点
        openEventMakerWindow(e) {
          this.eventMakerWindow.open(this.map, e.target.getPosition());
        },
        //初始化事件点
        getEventMakerWindow() {
          this.eventMakerWindow = new AMap.InfoWindow({
            isCustom: true,  //使用自定义窗体
            content: this.$refs.eventMakerPopup.$el,
            offset: new AMap.Pixel(0, -60)
          });

        },
        //路面颠簸
        roadCamberEvent(data){
          if(!this.vehicleEventIsOpen){
            return
          }
          let makerData = {"icon":bumpyEventIcon,"position": [data.longitude, data.latitude],"type":"event","option":"roadCamber"}
          this.createEventMaker(makerData,data)
        },
        //湿滑
        slipperyPointEvent(data){
          if(!this.vehicleEventIsOpen){
            return
          }
          let makerData = {"icon":slipperyPointIcon,"position":[data.longitude, data.latitude],"type":"event","option":"slippery"}
          this.createEventMaker(makerData,data)
        },
        // 积水
        waterPointEvent(data){
          if(!this.vehicleEventIsOpen){
            return
          }
          let makerData = {"icon":waterPointIcon,"position":[data.longitude, data.latitude],"type":"event","option":"water"}
          this.createEventMaker(makerData,data)
        },
        //结冰
        icePointEvent(data){
          if(!this.vehicleEventIsOpen){
            return
          }
          let makerData = {"icon":waterPointIcon,"position":[data.longitude, data.latitude],"type":"event","option":"ice"}
          this.createEventMaker(makerData,data)
        },
        //低附着点
        lowAttachmentPointEvent(data){
          if(!this.vehicleEventIsOpen){
            return
          }
          let makerData = {"icon":slipperyPointIcon,"position":[data.longitude, data.latitude],"type":"event","option":"lowAttachment"}
          this.createEventMaker(makerData,data)
        },

        removeEventMakers(key){
          if(key === 'roadCamber'){
            if(this.roadCamberMakerList.length > 0){
              this.map.remove(this.roadCamberMakerList)
              this.roadCamberMakerList = []
            }
          }else if(key === 'slippery'){
            if(this.slipperyPointMakerList.length > 0){
              this.map.remove(this.slipperyPointMakerList)
              this.slipperyPointMakerList = []
            }
          }else if(key === 'water'){
            if(this.waterPointMakerList.length > 0){
              this.map.remove(this.waterPointMakerList)
              this.waterPointMakerList = []
            }
          }else if(key === 'ice'){
            if(this.icePointMakerList.length > 0){
              this.map.remove(this.icePointMakerList)
              this.icePointMakerList = []
            }
          }else if(key == 'lowAttachment'){
            if(this.lowAttachmentMakerList.length > 0){
              this.map.remove(this.lowAttachmentMakerList)
              this.lowAttachmentMakerList = []
            }
          } else {
            if(this.roadCamberMakerList.length > 0){
              this.map.remove(this.roadCamberMakerList)
              this.roadCamberMakerList = []
            }
            if(this.slipperyPointMakerList.length > 0){
              this.map.remove(this.slipperyPointMakerList)
              this.slipperyPointMakerList = []
            }
            if(this.waterPointMakerList.length > 0){
              this.map.remove(this.waterPointMakerList)
              this.waterPointMakerList = []
            }
            if(this.icePointMakerList.length > 0){
              this.map.remove(this.icePointMakerList)
              this.icePointMakerList = []
            }
            if(this.lowAttachmentMakerList.length > 0){
              this.map.remove(this.lowAttachmentMakerList)
              this.lowAttachmentMakerList = []
            }
          }
        },
      queryBumpy24h(){
        //颠簸
        http.post("get-last-24h-bump-event",{hour:this.historyTime}).then(res =>{
          if(res.data && res.data.length > 0){
            this.removeEventMakers('roadCamber')
            res.data.forEach(item =>{
              console.log("item")
              console.log(item)
              let makerData = {"icon":bumpyEventIcon,"position":[item.longitude, item.latitude], "type":"history","option":"roadCamber"}
              this.createEventMaker(makerData,item)
            })
          }
        })
      },
      querySlippery24h(){
