        http.post("get-last-24h-slip-event",{hour:this.historyTime}).then(res =>{
          if(res.data && res.data.length > 0){
            this.removeEventMakers('slippery')
            res.data.forEach(item =>{
              let makerData = {"icon":slipperyPointIcon,"position":[item.longitude, item.latitude],"type":"history","option":"slippery"}
              this.createEventMaker(makerData,item)
            })
          }
        })
