        //矢量图折线
      createPolyline(color,gps,num) {

        let polyline = new AMap.Polyline({
          path: gps,
          borderWeight: 6, // 线条宽度，默认为 1
          strokeColor: color, // 线条颜色npm
          lineJoin: 'round' // 折线拐点连接处样式
        });
        if(num === 1){
          this.realTimePolylineArray1.push(polyline)
        }else {
          this.realTimePolylineArray2.push(polyline)
        }

        this.map.add(polyline)

      },

      delRealNetPolyline(){
        this.map.remove(this.realTimePolylineArray1)
        this.map.remove(this.realTimePolylineArray2)
        this.realTimePolylineArray1 = []
        this.realTimePolylineArray2 = []
        this.roadColorV2 = ""
        this.roadColorV1 = ""
        this.polylineEndV2 = ""
        this.polylineBeginV2 = ""
        this.polylineBeginV1 = ""
        this.polylineEndV1 = ""
        this.isDelNet = false
      },

      roadNetSwitch(){
        if(this.isDrawNet){
          this.delRealNetPolyline()
        }else {
          //this.getHistoryCarPolyline(1)
        }

      },
      createV2PolylineArray(item){
        if(item === undefined){
          return;
        }

          let color = ''

          if (this.roadNetType == 'slippery') {
            color = item.EN_color
          } else if(this.roadNetType == 'friction'){
            color = item.G_color
          }else {
            color = item.TS_color
          }
        if (this.polylineBeginV2.length == 0) {
          this.polylineBeginV2 = new AMap.LngLat(item.coordinates.longitude, item.coordinates.latitude)
          this.roadColorV2 = color
          this.pervColorV2 = color

        } else {

          if (this.polylineEndV2.length == 0) {
            //如果终点离起点距离太远 终点变起点重新画线
            let dis =AMap.GeometryUtil.distance(this.polylineBeginV2,new AMap.LngLat(item.coordinates.longitude,item.coordinates.latitude));
            if(dis < 1){
              return
            }
            if (dis > 500 ) {
              this.polylineBeginV2 = new AMap.LngLat(item.coordinates.longitude, item.coordinates.latitude)
              this.polylineEndV2 = []
              this.pervColorV2 = color
              this.roadColorV2 = color
              let gpsArray2 = []
              gpsArray2.push(new AMap.LngLat(item.coordinates.longitude, item.coordinates.latitude))
              this.createPolyline(color,gpsArray2,2)

            } else {
              this.polylineEndV2 = new AMap.LngLat(item.coordinates.longitude,item.coordinates.latitude)

              //一样
              if(this.roadColorV2 == color ){

                if(this.realTimePolylineArray2.length > 0 && this.roadColorV2 == this.pervColorV2 ){

                  let gpsPath2 = this.realTimePolylineArray2[this.realTimePolylineArray2.length - 1].getPath()
                  gpsPath2.push(this.polylineEndV2)
                  this.realTimePolylineArray2[this.realTimePolylineArray2.length - 1].setPath(gpsPath2)
                  this.pervColorV2 = this.roadColorV2
                  this.polylineBeginV2 = this.polylineEndV2

                  this.polylineEndV2 = []
                }else {

                  let gpsArray2 = []
                  gpsArray2.push(this.polylineBeginV2)
                  gpsArray2.push(this.polylineEndV2)
                  this.createPolyline(this.roadColorV2,gpsArray2,2)
                  this.pervColorV2 = this.roadColorV2
                  this.polylineBeginV2 = this.polylineEndV2
                  this.roadColorV2 = color
                  this.polylineEndV2 = []
                }
              }else {

                //颜色不一样
                let gpsArray2 = []
                gpsArray2.push(this.polylineBeginV2)
                gpsArray2.push(this.polylineEndV2)
                this.createPolyline(this.roadColorV2,gpsArray2,2)
                this.pervColorV2 = this.roadColorV2
                this.roadColorV2 = color
                this.polylineBeginV2 = this.polylineEndV2
                this.polylineEndV2 = []

              }

            }

          }else {
            this.polylineEndV2 = []
          }
        }
      },

      createV1PolylineArray(item) {
        if(item == undefined){
          return;
        }
        let color = ''
        if (this.roadNetType == 'slippery') {
          color = item.EN_color
        } else if(this.roadNetType == 'friction'){
          color = item.G_color
        }else {
          color = item.TS_color
        }
        //第一个点
        if(this.polylineBeginV1.length == 0){
          this.polylineBeginV1 = new AMap.LngLat(item.coordinates.longitude,item.coordinates.latitude)
          this.roadColorV1 = color
          this.pervColorV1 = color
        }else {

          if(this.polylineEndV1.length == 0){
            //如果终点离起点距离太远 终点变起点重新画线
            let dis =AMap.GeometryUtil.distance(this.polylineBeginV1,new AMap.LngLat(item.coordinates.longitude,item.coordinates.latitude));
            if(dis < 1){
              return
            }
            if(dis > 500 ){
              this.polylineBeginV1 = new AMap.LngLat(item.coordinates.longitude,item.coordinates.latitude)
              this.polylineEndV1 = []
              this.roadColorV1 = color
              this.pervColorV1 = color
              let gpsArray2 = []
              gpsArray2.push(new AMap.LngLat(item.coordinates.longitude, item.coordinates.latitude))
              this.createPolyline(color,gpsArray2,1)
            }else {
              this.polylineEndV1 = new AMap.LngLat(item.coordinates.longitude,item.coordinates.latitude)
              //一样
              if(this.roadColorV1 == color){
                if(this.realTimePolylineArray1.length > 0 && this.roadColorV1 == this.pervColorV1){
                  let gpsPath = this.realTimePolylineArray1[this.realTimePolylineArray1.length - 1].getPath()
                  gpsPath.push(this.polylineEndV1)
                  this.realTimePolylineArray1[this.realTimePolylineArray1.length - 1].setPath(gpsPath)
                  this.pervColorV1 = this.roadColorV1
                  this.polylineBeginV1 = this.polylineEndV1
                  this.polylineEndV1 = []
                }else {
                  let gpsArray = []
                  gpsArray.push(this.polylineBeginV1)
                  gpsArray.push(this.polylineEndV1)
                  this.createPolyline(this.roadColorV1,gpsArray,1)
                  this.pervColorV1 = this.roadColorV1
                  this.polylineBeginV1 = this.polylineEndV1
                  this.roadColorV1 = color
                  this.polylineEndV1 = []
                }

              }else {
                //不一样
                let gpsArray = []
                gpsArray.push(this.polylineBeginV1)
                gpsArray.push(this.polylineEndV1)
                this.createPolyline(this.roadColorV1,gpsArray,1)
                this.pervColorV1 = this.roadColorV1
                this.roadColorV1 = color
                this.polylineBeginV1 = this.polylineEndV1
                this.polylineEndV1 = []
              }
            }
          }else {
            this.polylineBeginV1 = []
          }
        }
      },
    }
}
</script>

