        return {
            id: "",
            sn: "",
            speed: 0,
            eventCount: 0,
            plateNumber: "",
            lat: 0,
            lan: 0,
            imgUrl: require("../assets/img/headImg.png")
        }
    },
    watch: {
      allVehicleData(val){
        //console.log("allVehicleData");
        //console.log(val);
        Object.entries(val).forEach(([key, value]) => {
          if(this.vehicleId ===  key){
            // this.id = value.deviceId
            // this.sn = value.serialNumber
            this.speed = value.speed
            this.plateNumber = value.plateNumber
            // this.eventCount = value.eventCount
            this.lat= value.coordinates.latitude;
            this.lan= value.coordinates.longitude;
          }
        });
      }
    },
}
