<template>
    <div class="road-info">
        <div class="title">历史24小时路面状态</div>
        <div id="friction" ref="chartContainer" class="friction-chart"></div>
        <div class="condition">
            <div class="condition-title">道路实时路况</div>
            <div class="infos">
                <div class="info">
                  <select class="sensor-select" v-model="sensorItem" @change="changeDate" >
                    <option v-for="sensor in sensors" :key="sensor.key" :value="sensor.key">
                      <div class="option">{{sensor.value}}</div>
                    </option>
                  </select>
                </div>

                <div class="info" :class="airChecked ? 'infochecked': ''"  @click="infoBtn('airTemperature')" >
                    <h6>空气温度</h6>
                    <p>{{ sensorData.airTemperature }}℃</p>
                </div>
                <div class="info" :class="roadChecked ? 'infochecked': ''"   @click="infoBtn('roadSurfaceTemperature')" >
                  <h6>路面温度</h6>
                  <p>{{ sensorData.roadSurfaceTemperature }}℃</p>
                </div>
                <div class="info" :class="relativeChecked ? 'infochecked': ''"  @click="infoBtn('relativeHumidity')" >
                  <h6>相对湿度</h6>
                  <p>{{ sensorData.relativeHumidity }}%</p>
                </div>
<!--              >-->
<!--                </div>-->
<!--                <div class="info" :class="rainChecked ? 'infochecked': ''" @click="infoBtn('rainIntensity')" v-show="sensorItem == 5">-->
<!--                  <h6>雨量强度</h6>-->
<!--                  <p>{{ sensorData.rainIntensity }}mm</p>-->
<!--                </div>-->
<!--                <div class="info infochecked"   v-show="sensorItem == 3 || sensorItem == 4" @click="infoBtn('pondingDepth')">-->
<!--                  <h6>积水深度</h6>-->
<!--                  <p>{{ sensorData.waterLayerThickness }}mm</p>-->
<!--                </div>-->

            </div>
        </div>
    </div>
</template>

<script>
import {options} from '@/data/roadEchart'
export default {
    props: ['chartData','segmentInfo','sensorData'],
    data() {
        return {
            echarts: null,
            roadSurfaceTemperature: 0,    //路面温度
            airTemperature: 0,            //空气温度
            friction: 0,                  //附着系数
            /*waterThickness: 0,            //水膜厚度
             */
            waterLayerThickness : 0,        //水膜厚度
            relativeHumidity: 0,           //相对湿度
            rainIntensity: 0,              //降雨强度
            echartsTitle: 'airTemperature',
            girdTitle: '空气温度',          //当前选项
            curSegmentInfo: null,
            sensors:[ {value:'文惠路与锦绣路',key:1 },
                      {value:'先锋中路与新锡路',key:2 },
                      {value:'机场路-泰山路',key:3 },
                      {value:'高浪路-兴梁道',key:4},
                      {value:'运河西路',key:5 },],

            sensorItem: 1,
            airChecked:true,
            roadChecked:false,
            relativeChecked:false,
            rainChecked:false

        }
    },
    watch: {
      chartData(val){
        this.drawEcharts(val);
      },
      deep:true
    },
    created() {
    },
    mounted() {
      console.info("mounted");

    const container = this.$refs.chartContainer;
    if (!container) return;

    const resizeObserver = new ResizeObserver(() => {
      if (container.offsetWidth > 0 && container.offsetHeight > 0) {
        if (!this.echarts) {
          this.initEcharts(this.chartData);
        } else {
          this.echarts.resize();
        }
      }
    });

    resizeObserver.observe(container);

    this.sensorItem = this.sensors[0].key;

    window.addEventListener('resize', () => this.echarts?.resize());
  },
  methods: {
      changeDate(val){
        this.sensorItem = val.target.value
        this.$emit('changesensor',val.target.value)
        this.airChecked = true
        this.roadChecked = false
        this.relativeChecked = false
        this.rainChecked = false
        this.girdTitle = "空气温度"
        // if(val.target.value == 1 || val.target.value == 2 || val.target.value == 5){
        //   this.airChecked = true
        //   this.roadChecked = false
        //   this.relativeChecked = false
        //   this.rainChecked = false
        //   this.girdTitle = "空气温度"
        // }else {
        //   this.airChecked = false
        //   this.roadChecked = false
        //   this.relativeChecked = false
        //   this.rainChecked = false
        //   this.girdTitle = "积水深度"
        // }
      },
      infoBtn(val){
        this.$emit('changeType',val)
        if(val == 'airTemperature'){
          this.airChecked = true
          this.roadChecked = false
          this.relativeChecked = false
          this.rainChecked = false
          this.girdTitle = '空气温度'
        }else if(val == 'roadSurfaceTemperature'){
          this.airChecked = false
          this.roadChecked = true
          this.relativeChecked = false
          this.rainChecked = false
          this.girdTitle = '路面温度'
        }else if(val == 'relativeHumidity'){
          this.airChecked = false
          this.roadChecked = false
          this.relativeChecked = true
          this.rainChecked = false
          this.girdTitle = '相对湿度'
        }else if(val == 'rainIntensity'){
          this.airChecked = false
          this.roadChecked = false
          this.relativeChecked = false
          this.rainChecked = true
          this.girdTitle = '雨量强度'
        }else if (val == "waterLayerThickness") {
          this.airChecked = false
          this.roadChecked = false
          this.relativeChecked = false
          this.rainChecked = false
          this.girdTitle = '积水深度'
        }
      },
      initEcharts(data) {
        const container = this.$refs.chartContainer;
        if (!container) {
          console.warn("Chart container not ready");
          return;
        }
        this.echarts = this.$echarts.init(container);

        if (!Array.isArray(data) || data.length === 0) {
          this.echarts.clear();
          return;
        }

        this.echarts.setOption(options(data, this.girdTitle));
        this.echarts.resize();
      },
      drawEcharts(val) {
        if (!this.echarts) return;
        console.log("Drawing chart with data:", val);
        if (!Array.isArray(val) || val.length === 0) {
          this.echarts.clear();
          return;
        }
        this.echarts.setOption(options(val,this.girdTitle))
        this.echarts.resize();
      }
    }
}
</script>

